<script>
  (function () {
  function run() {
    var list = document.querySelector('.rm-archive-results .rm-archive-list');
    if (!list) return;

    var query = (new URLSearchParams(window.location.search).get('s') || '').trim();

    /* ---------- Resalta la palabra buscada ---------- */
    if (query.length >= 2) {
      var words = query.split(/\s+/).filter(function (w) { return w.length >= 3; });
      if (words.length) {
        var escaped = words.map(function (w) { return w.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); });
        var re = new RegExp('(' + escaped.join('|') + ')', 'gi');
        list.querySelectorAll('.entry-title a, .post-content-inner').forEach(function (root) {
          var walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
          var nodes = [];
          while (walker.nextNode()) nodes.push(walker.currentNode);
          nodes.forEach(function (node) {
            var text = node.nodeValue;
            re.lastIndex = 0;
            if (!re.test(text)) return;
            var frag = document.createDocumentFragment();
            var last = 0;
            text.replace(re, function (match, _g, offset) {
              frag.appendChild(document.createTextNode(text.slice(last, offset)));
              var mark = document.createElement('mark');
              mark.className = 'rm-hit';
              mark.textContent = match;
              frag.appendChild(mark);
              last = offset + match.length;
            });
            frag.appendChild(document.createTextNode(text.slice(last)));
            node.parentNode.replaceChild(frag, node);
          });
        });
      }
    }

    /* ---------- Sin resultados: mensaje útil ---------- */
    if (!list.querySelector('.et_pb_post')) {
      var old = list.querySelector('.entry, .not-found-title');
      var box = document.createElement('div');
      box.className = 'rm-archive-empty';

      var icon = document.createElement('span');
      icon.className = 'rm-archive-empty__icon';
      icon.setAttribute('aria-hidden', 'true');
      icon.innerHTML = '<svg width="24" height="24" viewBox="0 0 24 24" fill="none"><circle cx="11" cy="11" r="7" stroke="currentColor" stroke-width="1.8"/><path d="m20 20-3.5-3.5" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/></svg>';
      box.appendChild(icon);

      var h = document.createElement('h2');
      h.textContent = query ? 'No hemos encontrado nada para «' + query + '»' : 'Todavía no hay artículos aquí';
      box.appendChild(h);

      var p = document.createElement('p');
      p.textContent = 'Prueba con otra palabra, mira uno de estos temas o pregúntanos directamente: te respondemos nosotros.';
      box.appendChild(p);

      var links = document.createElement('div');
      links.className = 'rm-archive-empty__links';
      document.querySelectorAll('.rm-archive-search__chips a').forEach(function (a) {
        var c = document.createElement('a');
        c.href = a.href;
        c.textContent = a.textContent;
        links.appendChild(c);
      });
      var contact = document.createElement('a');
      contact.href = '/contacto/';
      contact.className = 'is-primary';
      contact.textContent = 'Pregúntanos';
      links.appendChild(contact);
      box.appendChild(links);

      if (old) {
        var target = old.classList.contains('entry') ? old : old.parentNode;
        target.parentNode.replaceChild(box, target);
      } else {
        list.appendChild(box);
      }
    }
  }

